using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.Now.AddDays(-3), EstimatedDelivery = DateTime.Now.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-001235", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.Now.AddDays(-5), EstimatedDelivery = DateTime.Now, CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-001236", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.Pending, ShippedDate = DateTime.Now, EstimatedDelivery = DateTime.Now.AddDays(4), CustomerEmail = "carol@example.com", Description = "Medical supplies - 5 boxes" },
        new() { Id = 4, TrackingNumber = "TRK-001237", Origin = "Houston, TX", Destination = "Boston, MA", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.Now.AddDays(-7), EstimatedDelivery = DateTime.Now.AddDays(-1), CustomerEmail = "alice@example.com", Description = "Auto parts - 3 crates" },
        new() { Id = 5, TrackingNumber = "TRK-001238", Origin = "Phoenix, AZ", Destination = "Portland, OR", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.Now.AddDays(-4), EstimatedDelivery = DateTime.Now.AddDays(3), CustomerEmail = "dave@example.com", Description = "Perishable goods - refrigerated" },
        new() { Id = 6, TrackingNumber = "TRK-001239", Origin = "Atlanta, GA", Destination = "San Francisco, CA", Status = ShipmentStatus.PickedUp, ShippedDate = DateTime.Now, EstimatedDelivery = DateTime.Now.AddDays(5), CustomerEmail = "bob@example.com", Description = "Clothing - 10 boxes" },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        var shipments = _shipments
            .Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase))
            .ToList();
        return Task.FromResult(shipments);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            await service.GetAllShipmentsAsync());

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
            await service.GetShipmentsByCustomerAsync(email));

        group.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            await service.UpdateShipmentStatusAsync(id, status);
            return Results.NoContent();
        });
    }
}

